pub fn by_id(protocol_id: u32) -> Option<&'static SoundEventDef> {
    SOUND_EVENTS
        .binary_search_by_key(&protocol_id, |e| e.id)
        .ok()
        .map(|idx| &SOUND_EVENTS[idx])
}

pub fn by_key(key: &str) -> Option<&'static SoundEventDef> {
    let full = key.strip_prefix("minecraft:").unwrap_or(key);
    SOUND_EVENTS
        .iter()
        .find(|e| e.key.strip_prefix("minecraft:").unwrap_or(e.key) == full)
}
